            (*graph).edges as *mut libc::c_void,
            ((*graph).capacity as usize) * std::mem::size_of::<Edge>(),
        ) as *mut Edge;
    }
    let e: *mut Edge = (*graph).edges.offset((*graph).edge_count as isize);
    (*e).from = from;
    (*e).to = to;
    (*e).weight = weight;
    (*graph).edge_count += 1;
}

